import type { FC } from 'react';

export const FormField: FC<{
  label: string;
  value?: string;
  placeholder?: string;
}> = ({ label, value, placeholder = 'Enter value...' }) => (
  <div style={{ marginBottom: 14 }}>
    <label
      style={{
        display: 'block',
        marginBottom: 4,
        fontSize: 12,
        fontWeight: 600,
        color: '#3e3e3c'
      }}
    >
      {label}
    </label>
    <input
      type="text"
      defaultValue={value}
      placeholder={placeholder}
      style={{
        width: '100%',
        boxSizing: 'border-box',
        padding: '8px 12px',
        border: '1px solid #c9c9c9',
        borderRadius: 4,
        fontSize: 13,
        color: '#181818',
        background: '#fff'
      }}
    />
  </div>
);
